-- Storefront & checkout: featured products, customer tracking tokens, payment links,
-- idempotent checkout and a sequence for human order numbers.

-- AlterTable
ALTER TABLE "Product" ADD COLUMN     "featuredOrder" INTEGER,
ADD COLUMN     "isFeatured" BOOLEAN NOT NULL DEFAULT false;

-- AlterTable: publicToken is added nullable, backfilled for existing orders, then required.
ALTER TABLE "Order" ADD COLUMN     "idempotencyKey" TEXT,
ADD COLUMN     "paidAt" TIMESTAMP(3),
ADD COLUMN     "paymentUrl" TEXT,
ADD COLUMN     "publicToken" TEXT;

-- 32 random bytes (from two v4 UUIDs, generated by PostgreSQL's CSPRNG) as base64url.
UPDATE "Order"
SET "publicToken" = translate(
  rtrim(
    encode(
      decode(
        replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', ''),
        'hex'
      ),
      'base64'
    ),
    '='
  ),
  '+/',
  '-_'
)
WHERE "publicToken" IS NULL;

ALTER TABLE "Order" ALTER COLUMN "publicToken" SET NOT NULL;

-- CreateIndex
CREATE UNIQUE INDEX "Order_publicToken_key" ON "Order"("publicToken");

-- CreateIndex
CREATE UNIQUE INDEX "Order_idempotencyKey_key" ON "Order"("idempotencyKey");

-- CreateIndex
CREATE INDEX "Product_isFeatured_featuredOrder_idx" ON "Product"("isFeatured", "featuredOrder");

-- Order numbers (ZAM-<year>-<nnnnnn>) come from this sequence: atomic, gap-tolerant and safe
-- under concurrent checkouts. Not modelled in schema.prisma; read with nextval().
CREATE SEQUENCE IF NOT EXISTS "order_number_seq" START WITH 101;
